    private val sources: Array<String> by lazy {
        arrayOf(
            CHUNKS_COARSE.joinToString(""),
            CHUNKS_MEDIUM.joinToString(""),
            CHUNKS_FINE.joinToString("")
        )
    }

    private val pointCounts: IntArray by lazy {
        IntArray(LOD_COUNT) { countTokens(sources[it]) }
    }

    /** 该精度档的编码串（首次调用拼接并缓存）。lod 越界时按 coerceIn 处理。 */
    fun source(lod: Int): String = sources[lod.coerceIn(0, LOD_COUNT - 1)]

    /** 该精度档的点数（不含分隔符），供规模断言/测试用。 */
    fun tokenCount(lod: Int): Int = pointCounts[lod.coerceIn(0, LOD_COUNT - 1)]
}

/** 64 字符表的逆表：`ALPHABET[i]` 的字符映射到 `i`。字母表不含 `/`，故 `/` 必是分隔符。 */
private val WORLD_DECODE: IntArray = IntArray(128) { -1 }.also { table ->
    "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz-_"
        .forEachIndexed { i, c -> table[c.code] = i }
}

/** 数一档的点数（不含 `/`），每点固定 4 字符。 */
private fun countTokens(src: String): Int {
    var chars = 0
    for (k in src.indices) {
        if (src[k] != '/') chars++
    }
    return chars / 4
}

/** 解 2 个 base64 字符成 12 位整数；任一字符非法时返回 -1。 */
private fun decodePair(hi: Char, lo: Char): Int {
    val a = if (hi.code < 128) WORLD_DECODE[hi.code] else -1
    val b = if (lo.code < 128) WORLD_DECODE[lo.code] else -1
    if (a < 0 || b < 0) return -1
    return (a shl 6) or b
}

@Volatile
private var worldCache: Array<WorldLandmass?> = arrayOfNulls(WorldMapData.LOD_COUNT)

/** 按精度档解码。同一 lod 多次调用返回**同一实例**（内部缓存，渲染期复用）。 */
internal fun decodeWorld(lod: Int): WorldLandmass {
    val level = lod.coerceIn(0, WorldMapData.LOD_COUNT - 1)
    val cached = worldCache[level]
    if (cached != null) return cached
    val built = decodeWorldSource(WorldMapData.source(level))
    // 竞态下最多多解一次；此后所有调用都命中缓存里同一个实例。
    worldCache[level] = built
    return built
}

/**
 * 真正的解码实现，单趟扫描。
 *
 * 环是**隐式闭合**的：`ringLength` 个点画一圈。数组按上界一次性分配（一个环最少
 * 3 点 = 12 字符 + 1 个分隔符 = 13 字符，故 `src.length / 13 + 2` 必然够用），最后
 * `copyOf` 收敛到实际环数。
 *
 * 面对损坏 / 被截断的字符串时保守跳过而不是抛异常：字符数不是 4 的倍数、含非法
 * base64 字符、点数少于 3（画不成环）的环统统跳过。数据若被外部手段破坏，最坏结果
 * 只是少画几块地，而不是整个可视化崩掉。
 */
private fun decodeWorldSource(src: String): WorldLandmass {
    val n = src.length
    val maxRings = n / 13 + 2
    val starts = IntArray(maxRings)
    val lengths = IntArray(maxRings)
    val lon = FloatArray(n / 4)
    val lat = FloatArray(n / 4)
    var rings = 0
    var points = 0
    var i = 0
    while (i < n) {
        while (i < n && src[i] == '/') i++
        if (i >= n) break
        val ringStart = i
        while (i < n && src[i] != '/') i++
        val chars = i - ringStart

        if (chars < 12 || chars % 4 != 0 || rings == maxRings || points + chars / 4 > lon.size) {
            continue
        }
        var k = 0
        var broken = false
        while (k < chars) {
            val base = ringStart + k
            val li = decodePair(src[base], src[base + 1])
            val ai = decodePair(src[base + 2], src[base + 3])
            if (li < 0 || ai < 0) {
                broken = true
                break
            }
            lon[points] = li / 4095f * 360f - 180f
            lat[points] = ai / 4095f * 180f - 90f
            points++
            k += 4
        }
        if (broken) {
            points -= k / 4
            continue
        }
        starts[rings] = points - chars / 4
        lengths[rings] = chars / 4
        rings++
    }
    return WorldLandmass(
        ringCount = rings,
        pointCount = points,
        ringStart = starts.copyOf(rings),
        ringLength = lengths.copyOf(rings),
        lon = lon.copyOf(points),
        lat = lat.copyOf(points),
    )
}
